(function(){'use strict';
const M=window.Ch5,$=id=>document.getElementById(id),E=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),F=(x,n=4)=>Number.isFinite(x)?Number(x.toFixed(n)).toLocaleString('zh-CN',{maximumFractionDigits:n}):'—',copy=x=>JSON.parse(JSON.stringify(x));
const names=['A 校门口','B 教学区','C 图书馆'],colors=['#244e79','#bb8637','#24664d','#876190'];let record={},A=[],P=[],aNames=[],gCfg=null;
function updateRuntimeStatus(){const failed=[...document.querySelectorAll('[id$="-error"]')].filter(e=>e.textContent.trim());const ready=Object.keys(record).length===4&&Object.values(record).every(Boolean);$('runtime-status').classList.toggle('runtime-failure',failed.length>0);if(failed.length){$('runtime-status').textContent='有 '+failed.length+' 项实验计算暂停，请检查对应实验的错误提示；其余实验仍可使用。';}else if(ready){$('runtime-status').textContent='四个实验已就绪。先预测、再改参，最后用计算过程解释变化。';}else{$('runtime-status').textContent='实验正在初始化。';}}
const val=id=>{const e=$(id);if(e.value.trim()===''||!e.checkValidity())throw new Error('请完整填写范围内的数值：'+(e.getAttribute('aria-label')||id));return Number(e.value);};
function table(id,heads,rows){$(id).innerHTML='<table><thead><tr>'+heads.map(x=>'<th scope="col">'+E(x)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map((x,i)=>'<'+(i?'td':'th scope="row"')+'>'+E(x)+'</'+(i?'td':'th')+'>').join('')+'</tr>').join('')+'</tbody></table>';}
function input(id,x,label,min=0,max=10000,step='any'){return `<input id="${id}" type="number" value="${x}" min="${min}" max="${max}" step="${step}" required aria-label="${E(label)}">`;}
function svgFrame(xmax,ymax,xlabel,ylabel){const X=x=>80+650*x/(xmax||1),Y=y=>325-245*y/(ymax||1);let s='<svg viewBox="0 0 840 420" role="img" aria-label="'+E(ylabel+'与'+xlabel)+'"><title>'+E(ylabel+'与'+xlabel)+'</title>';for(let j=0;j<=5;j++){const x=xmax*j/5,y=ymax*j/5;s+=`<line x1="80" x2="730" y1="${Y(y)}" y2="${Y(y)}" stroke="#dce3e9"/><text x="69" y="${Y(y)+5}" text-anchor="end">${F(y,2)}</text><text x="${X(x)}" y="351" text-anchor="middle">${F(x,2)}</text>`;}s+=`<text x="80" y="28" class="label">${E(ylabel)}</text><text x="405" y="401" text-anchor="middle">${E(xlabel)}</text>`;return {s,X,Y};}
function linePlot(id,series,xlabel,ylabel,current=null){const b=svgFrame(1,1,xlabel,ylabel);series.forEach((v,i)=>{b.s+=`<polyline points="${v.points.map(p=>b.X(p[0])+','+b.Y(p[1])).join(' ')}" fill="none" stroke="${colors[i%4]}" stroke-width="3"/><text x="${80+i*190}" y="58" style="fill:${colors[i%4]}">${E(v.name)}</text>`;});if(current!==null)b.s+=`<line x1="${b.X(current)}" x2="${b.X(current)}" y1="80" y2="325" stroke="#8795a6" stroke-dasharray="5 4"/>`;$(id).innerHTML=b.s+'</svg>';}
function matrixEditor(id,rows,labels,heads,prefix){$(id).innerHTML='<table><thead><tr><th>对象</th>'+heads.map(x=>'<th>'+E(x)+'</th>').join('')+'</tr></thead><tbody>'+rows.map((r,i)=>'<tr><th scope="row">'+E(labels[i])+'</th>'+r.map((x,k)=>'<td>'+input(`${prefix}-${i}-${k}`,x,labels[i]+' '+heads[k],prefix==='d'?.1:0,prefix==='d'?1000:10000)+'</td>').join('')+'</tr>').join('')+'</tbody></table>';}
function readMatrix(prefix,n,m){return Array.from({length:n},(_,i)=>Array.from({length:m},(_,k)=>val(`${prefix}-${i}-${k}`)));}
function bounds(lines){let pts=[0,1];for(let i=0;i<lines.length;i++)for(let j=i+1;j<lines.length;j++){const dm=lines[i].m-lines[j].m;if(Math.abs(dm)<1e-12)continue;const x=(lines[j].b-lines[i].b)/dm;if(x>0&&x<1)pts.push(x);}pts.sort((a,b)=>a-b);return pts.filter((x,i)=>!i||Math.abs(x-pts[i-1])>1e-9).filter(x=>{const scores=lines.map(l=>l.b+l.m*x),max=Math.max(...scores);return x===0||x===1||scores.filter(v=>Math.abs(v-max)<1e-8).length>1;});}
function refreshUtility(){try{const rows=readMatrix('u',3,3),w=val('u-weight-exact'),t=val('u-inner'),rule=$('u-rule').value,power=val('u-power'),directions=[0,1,2].map(k=>$('dir-'+k).value);const r=M.scoreLocations(rows,w,t,rule,power,directions);record.utility={rows,w,t,rule,power,directions,result:r};$('u-error').textContent='';$('u-results').hidden=false;$('w-out').textContent=F(w,6);$('t-out').textContent=F(t);$('u-weight').disabled=rule!=='add';$('u-weight-exact').disabled=rule!=='add';$('u-result').textContent='当前推荐：'+r.winners.map(i=>names[i]).join('、')+'；效用 '+F(Math.max(...r.scores))+'。'+(r.winners.length>1?'保留并列。':'');const formulas={add:`H=${F(w)}u收益 + ${F(1-w)}V；叶节点权重为 ${F(w)} / ${F((1-w)*t)} / ${F((1-w)*(1-t))}`,distance:'H=1−√[((1−u收益)²+(1−V)²)/2]；顶层等重要，不使用w。',replace:'H=1−(1−u收益)(1−V)；顶层等重要，不使用w。',product:'H=u收益×V；顶层等重要，不使用w。',mixed:'H=0.4u收益+0.4V+0.2u收益V；c₁=c₂=0.4、γ=1.25，不使用w。'};$('u-formula').textContent=`V=${F(t)}u步行 + ${F(1-t)}u体验；`+formulas[rule];table('u-steps',['地点','收益效用','步行效用','体验效用','服务V','总效用H','原数据支配检查'],r.mapped.map((u,i)=>[names[i],...u.map(x=>F(x)),F(r.experience[i]),F(r.scores[i]),r.dominated[i]?'被另一地点支配':'未被支配']));if(rule==='add'){const lines=r.mapped.map((u,i)=>({b:r.experience[i],m:u[0]-r.experience[i]}));linePlot('u-plot',lines.map((l,i)=>({name:names[i],points:[[0,l.b],[1,l.b+l.m]]})),'收益层权重 w（虚线为当前值）','加法总效用 H',w);$('u-boundaries').innerHTML='端点与最优切换点（点击使用未舍入值）：'+bounds(lines).map(x=>`<button class="point-button" type="button" data-w="${x}">${F(x,8)}</button>`).join(' ');}else{linePlot('u-plot',r.experience.map((v,i)=>({name:names[i],points:Array.from({length:41},(_,j)=>[j/40,M.combine(j/40,v,rule,w)])})),'假设的收益效用 u（固定各地点当前服务V）','所选规则的响应曲线');$('u-boundaries').textContent='此图改变的是收益效用，不是权重。实际得分见上表。';}const clipped=rows.some(r=>r.some((v,k)=>v>[15,12,100][k]));$('u-warning').textContent=(directions.join()!=='benefit,cost,benefit'?'已改变教学指标的原始方向，请为这种偏好给出理由。 ':'')+(clipped?'有指标超出锚点范围，映射已截断；请检查是否需要重设评价量表。 ':'')+'效用刻度与权重共同表达偏好；当前模型没有处理利润波动。';}catch(e){record.utility=null;$('u-error').textContent=e.message;$('u-results').hidden=true;}finally{updateRuntimeStatus();}}
function initUtility(){matrixEditor('utility-editor',M.presets.locations,names,['年净收益 / 万元','典型步行 / 分钟','体验 / 100分'],'u');$('u-weight').value=.6;$('u-weight-exact').value=.6;$('u-inner').value=.5;$('u-rule').value='add';$('u-power').value='1';['benefit','cost','benefit'].forEach((v,k)=>$('dir-'+k).value=v);refreshUtility();}
function initAHP(){const key=$('a-case').value;A=key==='cycle'?[[1,9,1/9],[1/9,1,9],[9,1/9,1]]:key==='consistent'?[[1,2,4],[.5,1,2],[.25,.5,1]]:key==='four'?[[1,2,4,4],[.5,1,2,2],[.25,.5,1,1],[.25,.5,1,1]]:[[1,3,5],[1/3,1,2],[1/5,.5,1]];aNames=['收益','便利','体验','环境'].slice(0,A.length);P=[[.5,.1,.2,.1],[.3,.3,.35,.2],[.2,.6,.45,.7]].map(r=>r.slice(0,A.length));$('a-editor').innerHTML='<table><thead><tr><th>行 / 列</th>'+aNames.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+A.map((r,i)=>'<tr><th scope="row">'+aNames[i]+'</th>'+r.map((x,j)=>'<td'+(i>=j?' class="matrix-readonly"':'')+'>'+(i<j?input(`a-${i}-${j}`,x,`${aNames[i]}相对${aNames[j]}`,1/9,9):`<span id="ar-${i}-${j}">${F(x,6)}</span>`)+'</td>').join('')+'</tr>').join('')+'</tbody></table>';matrixEditor('a-local',P,names,aNames.map(x=>x+'下局部权重'),'p');refreshAHP();}
function refreshAHP(){try{for(let i=0;i<A.length;i++)for(let j=i+1;j<A.length;j++){A[i][j]=val(`a-${i}-${j}`);A[j][i]=1/A[i][j];$('ar-'+j+'-'+i).textContent=F(A[j][i],6);}const r=M.ahp(A);$('a-result').textContent=`λmax=${F(r.lambda,6)}；CI=${F(r.ci,6)}；RI=${r.ri}；CR=${F(r.cr,6)}。${r.acceptable?'按教材阈值可接受。':'未达到教材一致性要求，请复核判断理由。'}`;table('a-steps',['准则','权重w','Aw','(Aw)ᵢ/wᵢ'],r.weights.map((v,i)=>[aNames[i],F(v,6),F(r.Aw[i],6),F(r.Aw[i]/v,6)]));const t=r.triads[0];$('a-triad').textContent=`最需要复核的三元组：${aNames[t.i]} / ${aNames[t.j]} / ${aNames[t.k]}。直接判断=${F(t.direct,6)}；间接判断=${F(t.indirect,6)}。对数差=${F(t.error,6)}，0表示这组三项完全传递一致。`;P=readMatrix('p',3,A.length);for(let k=0;k<A.length;k++){const z=M.sum(P.map(row=>row[k]));if(P.some(row=>row[k]>1)||Math.abs(z-1)>1e-6)throw new Error(aNames[k]+'下局部权重每项须在[0,1]，合计为1；当前合计'+F(z,6));}const total=P.map(row=>M.dot(row,r.weights));table('a-overall',['地点','各项贡献','总权重'],P.map((row,i)=>[names[i],row.map((v,k)=>`${F(v)}×${F(r.weights[k])}`).join(' + '),F(total[i],6)]));const other=M.sum(r.weights.slice(1));const series=P.map((row,i)=>({name:names[i],points:Array.from({length:21},(_,j)=>{const x=j/20;return [x,row[0]*x+M.sum(row.slice(1).map((v,k)=>v*r.weights[k+1]))/other*(1-x)];})}));linePlot('a-plot',series,'收益准则权重；其余权重保持原比例','方案总权重',r.weights[0]);const max=Math.max(...total);$('a-sensitivity').textContent='当前总排序第一：'+total.map((v,i)=>Math.abs(v-max)<1e-9?names[i]:null).filter(Boolean).join('、')+'。曲线是外部敏感性实验，未反写当前判断矩阵。';record.ahp={matrix:copy(A),local:copy(P),result:r,total};$('a-error').textContent='';}catch(e){record.ahp=null;$('a-error').textContent=e.message;$('a-result').textContent='计算暂停，请修正输入。';$('a-steps').innerHTML='';$('a-triad').textContent='';$('a-overall').innerHTML='';$('a-plot').innerHTML='';$('a-sensitivity').textContent='总排序暂停，修正输入后自动重算。';}finally{updateRuntimeStatus();}}
function initDEA(){const data=$('d-case').value==='weak'?M.presets.weak:M.presets.dea;matrixEditor('d-editor',data,['单位1','单位2','单位3','单位4'],['投入1','投入2','产出'],'d');$('d-unit').value=$('d-case').value==='weak'?'1':'3';refreshDEA();}
function refreshDEA(){try{const data=readMatrix('d',4,3),o=val('d-unit'),bcc=$('d-model').value==='bcc',all=data.map((_,i)=>M.dea(data,i,bcc)),r=all[o];record.dea={data,o,bcc,result:all};$('d-error').textContent='';$('d-results').hidden=false;$('d-result').textContent=`单位${o+1}：θ=${F(r.theta,6)}；${r.strong?'强有效':r.weakOnly?'仅弱有效：θ=1但仍有松弛':'径向无效率：存在同比例节省空间'}。${bcc?'BCC，Σλ=1。':'CCR，不约束Σλ。'}`;table('d-summary',['单位','θ','第二阶段标准化松弛和','判别'],all.map((v,i)=>['单位'+(i+1),F(v.theta,6),F(v.normalizedSlack,6),v.strong?'强有效':v.weakOnly?'仅弱有效':'径向无效率']));table('d-reference',['参照单位','λ','投入1贡献','投入2贡献','产出贡献'],r.lambda.map((v,i)=>['单位'+(i+1),F(v,6),F(v*data[i][0]),F(v*data[i][1]),F(v*data[i][2])]));table('d-checks',['约束','参照组合值','右端 / 基准','松弛'],[['投入1 ≤ θ×原投入',F(r.target[0]),F(r.theta*data[o][0]),F(r.inputSlack[0])],['投入2 ≤ θ×原投入',F(r.target[1]),F(r.theta*data[o][1]),F(r.inputSlack[1])],['产出 ≥ 原产出',F(r.target[2]),F(data[o][2]),F(r.outputSlack)],['λ之和',F(M.sum(r.lambda)),bcc?'必须为1':'CCR不限定为1','—']]);$('d-projection').textContent=`投入改进目标=(${F(r.target[0])}, ${F(r.target[1])})；产出目标=${F(r.target[2])}。总投入减少=(${F(data[o][0]-r.target[0])}, ${F(data[o][1]-r.target[1])})。实际实施还需检查技术、服务质量及不可调整资源。`;const pts=data.map(d=>[d[0]/d[2],d[1]/d[2]]),target=[r.target[0]/r.target[2],r.target[1]/r.target[2]],xmax=Math.max(...pts.map(p=>p[0]))*1.18,ymax=Math.max(...pts.map(p=>p[1]))*1.18,b=svgFrame(xmax,ymax,'每单位产出的投入1','每单位产出的投入2');if(!bcc){const efficient=pts.filter((_,i)=>all[i].strong).sort((a,b)=>a[0]-b[0]);if(efficient.length>1)b.s+=`<polyline points="${efficient.map(p=>b.X(p[0])+','+b.Y(p[1])).join(' ')}" fill="none" stroke="#24664d" stroke-width="3"/>`;}pts.forEach((p,i)=>b.s+=`<circle cx="${b.X(p[0])}" cy="${b.Y(p[1])}" r="${i===o?7:5}" fill="${colors[i]}"/><text x="${b.X(p[0])+9}" y="${b.Y(p[1])-9}" class="label">${i+1}</text>`);b.s+=`<line x1="${b.X(pts[o][0])}" y1="${b.Y(pts[o][1])}" x2="${b.X(target[0])}" y2="${b.Y(target[1])}" stroke="#132d49" stroke-dasharray="6 4"/><circle cx="${b.X(target[0])}" cy="${b.Y(target[1])}" r="8" fill="none" stroke="#132d49" stroke-width="2"/><text x="80" y="58">空心点：改进目标；${bcc?'BCC图仅作投入比观察，不代表完整前沿':'绿线：CCR强有效观察点的边界连接'}</text>`;$('d-plot').innerHTML=b.s+'</svg>';}catch(e){record.dea=null;$('d-error').textContent=e.message;$('d-results').hidden=true;}finally{updateRuntimeStatus();}}
function initGP(){gCfg=copy(M.presets[$('g-case').value]);$('g-context').textContent='变量：'+gCfg.names.join('、')+'。'+($('g-case').value==='textile'?'1千米需1小时；默认正常80小时，加班目标10小时。':'原题只惩罚目标1、2的超额和目标3的不足；注意多重最优。');$('g-hard').innerHTML='<table><thead><tr><th>硬约束</th><th>左侧</th><th>≤ 上限</th></tr></thead><tbody>'+gCfg.hard.map((h,i)=>`<tr><th>${E(h.name)}</th><td>${h.a[0]}x₁ + ${h.a[1]}x₂</td><td>${input('gh-'+i,h.b,h.name,-1000,1000)}</td></tr>`).join('')+'</tbody></table>';$('g-goals').innerHTML='<table><thead><tr><th>目标 / 左侧</th><th>目标值</th><th>偏差方向</th><th>优先级</th><th>同级权重</th></tr></thead><tbody>'+gCfg.goals.map((g,i)=>`<tr><th>${E(g.name)}<br>${g.a[0]}x₁ + ${g.a[1]}x₂</th><td>${input('gt-'+i,g.target,g.name+'目标值',-1000,1000)}</td><td><select id="gm-${i}" aria-label="${E(g.name)}偏差方向">${[['under','至少：罚不足'],['over','至多：罚超额'],['exact','恰好：两边罚']].map(([v,s])=>`<option value="${v}" ${v===g.mode?'selected':''}>${s}</option>`).join('')}</select></td><td>${input('gp-'+i,g.priority,g.name+'优先级',1,8,1)}</td><td>${input('gw-'+i,g.weight,g.name+'权重',.001,1000)}</td></tr>`).join('')+'</tbody></table>';refreshGP();}
function polygon(hard,xmax,ymax){let p=[[0,0],[xmax,0],[xmax,ymax],[0,ymax]];hard.forEach(h=>{const q=[];for(let i=0;i<p.length;i++){const a=p[i],b=p[(i+1)%p.length],va=M.dot(h.a,a)-h.b,vb=M.dot(h.a,b)-h.b;if(va<=1e-8)q.push(a);if((va<=0)!==(vb<=0)){const t=va/(va-vb);q.push([a[0]+t*(b[0]-a[0]),a[1]+t*(b[1]-a[1])]);}}p=q;});return p;}
function refreshGP(){try{const cfg=copy(gCfg);cfg.mode=$('g-mode').value;cfg.hard.forEach((h,i)=>h.b=val('gh-'+i));cfg.goals.forEach((g,i)=>Object.assign(g,{target:val('gt-'+i),mode:$('gm-'+i).value,priority:val('gp-'+i),weight:val('gw-'+i)}));const r=M.gp(cfg);record.gp={config:cfg,result:r};$('g-error').textContent='';$('g-results').hidden=false;['g-plot','g-deviations','g-stages','g-residuals','g-ties'].forEach(id=>$(id).innerHTML='');if(!r.feasible){$('g-result').textContent='硬约束不可行：没有同时满足限制的非负配置。调整优先级不能修复硬约束冲突。';return;}$('g-result').textContent=`一个最优配置：(x₁,x₂)=(${F(r.p[0],6)}, ${F(r.p[1],6)})。${cfg.mode==='lex'?'按优先级逐级比较。':'按普通加权总和比较；优先级数字未参与。'}`;table('g-deviations',['目标','实际 / 目标','不足d⁻','超额d⁺','被罚部分×权重'],r.details.map((d,i)=>[cfg.goals[i].name,F(d.actual)+' / '+F(cfg.goals[i].target),F(d.minus),F(d.plus),F(d.penalty)]));table('g-stages',['比较层','最优惩罚值'],r.vector.map((v,i)=>[cfg.mode==='lex'?'P'+r.priorities[i]:'加权总和',F(v,6)]));table('g-residuals',['硬约束','剩余容量（须≥0）'],cfg.hard.map((h,i)=>[h.name,F(r.hardResiduals[i],6)]));$('g-ties').textContent=r.ties.length>1?'同样最优的候选顶点：'+r.ties.map(p=>'('+p.map(x=>F(x,4)).join(', ')+')').join('、')+'；它们的凸组合也可能形成最优线段或区域。':'当前候选顶点中最优解唯一。参数变化可能产生并列最优。';const xmax=Math.max(1,...r.candidates.map(x=>x.p[0]))*1.12,ymax=Math.max(1,...r.candidates.map(x=>x.p[1]))*1.12,b=svgFrame(xmax,ymax,cfg.names[0],cfg.names[1]);const poly=polygon(cfg.hard,xmax,ymax);if(poly.length)b.s+=`<polygon points="${poly.map(p=>b.X(p[0])+','+b.Y(p[1])).join(' ')}" fill="#eaf1f8" stroke="#244e79" stroke-width="2"/>`;cfg.goals.forEach((g,i)=>{const pts=[];[[[1,0],0],[[1,0],xmax],[[0,1],0],[[0,1],ymax]].forEach(([a,v])=>{const p=M.solveLinear([g.a,a],[g.target,v]);if(p&&p[0]>=0&&p[0]<=xmax&&p[1]>=0&&p[1]<=ymax&&!pts.some(q=>Math.hypot(q[0]-p[0],q[1]-p[1])<1e-6))pts.push(p);});if(pts.length>=2)b.s+=`<line x1="${b.X(pts[0][0])}" y1="${b.Y(pts[0][1])}" x2="${b.X(pts[1][0])}" y2="${b.Y(pts[1][1])}" stroke="${colors[i%4]}" stroke-dasharray="5 4"/>`;});r.ties.forEach(p=>b.s+=`<circle cx="${b.X(p[0])}" cy="${b.Y(p[1])}" r="6" fill="#bb8637"/>`);b.s+='<text x="80" y="58">蓝色区域：硬约束可行域；虚线：目标线；金点：最优候选顶点</text>';$('g-plot').innerHTML=b.s+'</svg>';}catch(e){record.gp=null;$('g-error').textContent=e.message;$('g-results').hidden=true;}finally{updateRuntimeStatus();}}
const quiz=[['成本指标越小越好时，效用应怎样随成本变化？',['随成本增加而增大','随成本增加而减小','始终等于成本'],1,'方向必须符合偏好，之后才谈权重。'],['AHP 的 CR 通过，说明什么？',['所选方案一定正确','偏好变成客观事实','矩阵内部矛盾在所选阈值内'],2,'指标遗漏、数据错误与偏好偏差仍可能存在。'],['CCR参照系数之和0.8，能否直接判错？',['可以，必须等于1','不可以，CCR没有该约束','只要是小数都错误'],1,'BCC才增加Σλ=1。'],['θ=1但第二阶段有正松弛，属于什么？',['强有效','仅弱有效','数据必定录错'],1,'有单项投入或产出仍可改进。'],['至少达到目标值，应惩罚哪项？',['负偏差d⁻','正偏差d⁺','无条件两项都罚'],0,'不足是d⁻；超额并非这项目标要避免的方向。'],['严格优先级的正确处理是什么？',['随便给高层一个大权重','先锁定高层最优值，再优化下一层','把所有目标除以目标值'],1,'有限大权重一般不自动等价于严格优先级。'],['样本内DEA有效是否等于绝对优秀？',['是','否，取决于样本和技术假设','只要产出大就是'],1,'相对有效也可能来自比较对象弱或指标遗漏。'],['AHP得分、DEA效率、目标偏差能否直接相加？',['可以，因为都是数字','不可以，含义与方向不同','先保留两位小数就可以'],1,'先明确决策问题，各方法提供不同证据。']];
function navigate(){let id=location.hash.slice(1);if(!['utility','ahp','dea','gp','project','sources'].includes(id))id='utility';document.querySelectorAll('.panel').forEach(p=>p.hidden=p.id!==id);document.querySelectorAll('.side-nav a').forEach(a=>{const on=a.hash==='#'+id;a.classList.toggle('active',on);if(on)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});}
function init(){initUtility();initAHP();initDEA();initGP();$('utility').addEventListener('input',e=>{if(e.target.id==='u-weight')$('u-weight-exact').value=e.target.value;if(e.target.id==='u-weight-exact')$('u-weight').value=e.target.value;refreshUtility();});$('utility').addEventListener('change',refreshUtility);$('u-boundaries').addEventListener('click',e=>{const b=e.target.closest('[data-w]');if(b){$('u-weight-exact').value=b.dataset.w;$('u-weight').value=b.dataset.w;refreshUtility();}});$('u-reset').addEventListener('click',initUtility);$('a-case').addEventListener('change',initAHP);$('a-reset').addEventListener('click',initAHP);$('a-editor').addEventListener('input',refreshAHP);$('a-local').addEventListener('input',refreshAHP);$('d-case').addEventListener('change',initDEA);$('d-reset').addEventListener('click',initDEA);$('d-editor').addEventListener('input',refreshDEA);$('d-model').addEventListener('change',refreshDEA);$('d-unit').addEventListener('change',refreshDEA);$('g-case').addEventListener('change',initGP);$('g-reset').addEventListener('click',()=>{$('g-mode').value='lex';initGP();});$('g-mode').addEventListener('change',refreshGP);$('g-hard').addEventListener('input',refreshGP);$('g-goals').addEventListener('input',refreshGP);$('g-goals').addEventListener('change',refreshGP);$('quiz-questions').innerHTML=quiz.map((q,i)=>'<fieldset class="quiz-item"><legend>'+(i+1)+'. '+E(q[0])+'</legend>'+q[1].map((a,j)=>`<label><input type="radio" name="q${i}" value="${j}" required>${E(a)}</label>`).join('')+'</fieldset>').join('');$('quiz-form').addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.target);let count=0;$('quiz-result').innerHTML=quiz.map((q,i)=>{const ok=d.get('q'+i)!==null&&Number(d.get('q'+i))===q[2];if(ok)count++;return `<p>${ok?'✓':'✗'} ${i+1}. ${E(q[1][q[2]])}。${E(q[3])}</p>`;}).join('');$('quiz-result').insertAdjacentHTML('afterbegin',`<p><strong>${count} / ${quiz.length}。请解释错误题对应的模型含义。</strong></p>`);});$('quiz-form').addEventListener('reset',()=>{$('quiz-result').innerHTML='';});try{$('reflection').value=localStorage.getItem('decision-ch5-note')||'';}catch{}$('save-note').addEventListener('click',()=>{try{localStorage.setItem('decision-ch5-note',$('reflection').value);$('note-status').textContent='笔记已保存在本机。';}catch{$('note-status').textContent='当前浏览器无法保存，请导出或复制笔记。';}});$('export-record').addEventListener('click',()=>{refreshUtility();refreshAHP();refreshDEA();refreshGP();if(Object.values(record).some(r=>r===null)){$('note-status').textContent='导出暂停：请先修正各实验的输入错误。';return;}const blob=new Blob([JSON.stringify({chapter:5,created:new Date().toISOString(),...record,note:$('reflection').value},null,2)],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='第五章-实验记录.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('note-status').textContent='已导出当前四个实验及笔记。';});window.addEventListener('hashchange',navigate);navigate();updateRuntimeStatus();}
try{init();}catch(e){$('runtime-status').textContent='实验未能完整加载：'+e.message+'。请刷新或使用PDF与Python复算附件。';}
})();
